(function(){var W=430,mm=window.matchMedia.bind(window);function px(v,u){v=parseFloat(v);return u==="em"||u==="rem"?v*16:v}function ev(q){var parts=q.split(","),any=false;for(var i=0;i<parts.length;i++){var p=parts[i].toLowerCase();var rest=p.replace(/\((min|max)-width\s*:\s*[\d.]+(px|em|rem)?\)/g,"").replace(/\b(only|screen|all|and)\b/g,"").trim();if(rest)return null;var ok=true,re=/\((min|max)-width\s*:\s*([\d.]+)(px|em|rem)?\)/g,m,w=Math.min(innerWidth,W);while(m=re.exec(p)){var v=px(m[2],m[3]);if(m[1]==="min"&&w<v)ok=false;if(m[1]==="max"&&w>v)ok=false}if(ok)any=true}return any}window.matchMedia=function(q){if(innerWidth<=W||!/width/.test(q))return mm(q);var r=ev(q);if(r===null)return mm(q);return{matches:r,media:q,onchange:null,addListener:function(){},removeListener:function(){},addEventListener:function(){},removeEventListener:function(){},dispatchEvent:function(){return false}}}})();